/**
 * A Bitcoin UTXO input reference.
 */
public struct FfiBtcInput {
    public var txid: String
    public var vout: UInt32
    public var value: UInt64
    public var pubkeyHash: Data?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(txid: String, vout: UInt32, value: UInt64, pubkeyHash: Data?) {
        self.txid = txid
        self.vout = vout
        self.value = value
        self.pubkeyHash = pubkeyHash
    }
}



extension FfiBtcInput: Equatable, Hashable {
    public static func ==(lhs: FfiBtcInput, rhs: FfiBtcInput) -> Bool {
        if lhs.txid != rhs.txid {
            return false
        }
        if lhs.vout != rhs.vout {
            return false
        }
        if lhs.value != rhs.value {
            return false
        }
        if lhs.pubkeyHash != rhs.pubkeyHash {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(txid)
        hasher.combine(vout)
        hasher.combine(value)
        hasher.combine(pubkeyHash)
    }
}


